const HeroCard = ({ hero, onSelect }) => (
  <div
    onClick={() => onSelect(hero)}
    className="cursor-pointer rounded-2xl overflow-hidden shadow-lg transition-transform hover:scale-105 bg-slate-800">
    <img src={hero.img} alt={hero.name} className="w-full h-64 object-cover" />
    <div className="p-4 text-center text-white font-bold">{hero.name}</div>
  </div>
);
